# Mudanças feitas no painel depois da primeira versão do GitHub
def apply(s):
    def rep(a,b):
        nonlocal s
        assert a in s, 'NF: '+a[:80]
        s=s.replace(a,b,1)
    rep('<b class="rx-bt1">São Cristóvão Saúde</b><span class="rx-logo-sep"></span><span class="rx-bt2">Medicina Diagnóstica</span>',
        '<img class="rx-logo" src="logos/sao-cristovao-saude.png" alt="São Cristóvão Saúde"><span class="rx-logo-sep"></span><img class="rx-logo" src="logos/sao-cristovao-medicina-diagnostica.png" alt="São Cristóvão Medicina Diagnóstica">')
    rep("tempo desde o exame anterior · vale para Eletivos e Médicos","conta como repetição quando o mesmo paciente refaz o mesmo exame dentro desse prazo · muda também a aba Médicos")
    import re
    s2=re.sub(r'\n      <p class="rx-note"><b>Antes de cobrar:</b>.*?</p>','',s,count=1,flags=re.S); assert s2!=s; s=s2
    rep('<p>Repetições = exames pedidos pelo médico que o paciente já tinha feito no período. Em vermelho, quantas vezes a média.</p></div>\n        <div class="rx-ctl"><label>Ordenar por</label><div class="rx-seg" role="group" aria-label="Ordenar médicos"><button type="button" data-k="ordem_med" data-v="pac">Repetições por paciente</button><button type="button" data-k="ordem_med" data-v="custo">Custo por ano</button></div></div>',
        '<p>Contado paciente a paciente: se a Maria fez um hemograma e o médico pediu outro hemograma para ela, isso é 1 repetição na conta desse médico. Depois dividimos pelo número de pacientes que ele atendeu, para quem atende mais não sair na frente só pelo volume. Em vermelho, quantas vezes a média.</p></div>\n        <div class="rx-ctl"><label>Ordenar por</label><div class="rx-seg" role="group" aria-label="Ordenar médicos"><button type="button" data-k="ordem_med" data-v="pac">Repetições por paciente</button><button type="button" data-k="ordem_med" data-v="cpp">Custo por paciente</button><button type="button" data-k="ordem_med" data-v="custo">Custo total por ano</button></div></div>')
    rep('<thead><tr><th data-field="medico">Médico</th><th data-field="pacientes">Pacientes</th><th data-field="repeticoes">Repetições</th><th data-field="rep_por_paciente">Por paciente</th><th data-field="vs_media">× média</th><th data-field="pct_proprio">Do próprio pedido</th><th data-field="custo_repeticao_ano">Custo/ano</th></tr></thead>',
        '<thead><tr><th>Médico</th><th>Pacientes atendidos</th><th>Pacientes com repetição</th><th>Repetições</th><th>Repetições por paciente</th><th>× média</th><th>Do próprio pedido</th><th>Custo por paciente/ano</th><th>Custo total/ano</th></tr></thead>')
    rep("custo_repeticao_ano: +r.custo_repeticao * k}))\n      .sort((a, b) => o === 'custo' ? b.custo_repeticao_ano - a.custo_repeticao_ano : b.rep_por_paciente - a.rep_por_paciente).slice(0, 30); }});",
        "custo_repeticao_ano: +r.custo_repeticao * k,\n      pct_pac_rep: +r.pacientes_com_repeticao / +r.pacientes * 100, custo_por_paciente: +r.custo_repeticao * k / +r.pacientes}))\n      .sort((a, b) => o === 'custo' ? b.custo_repeticao_ano - a.custo_repeticao_ano : o === 'cpp' ? b.custo_por_paciente - a.custo_por_paciente : b.rep_por_paciente - a.rep_por_paciente).slice(0, 30); }});")
    rep("const val = r => o === 'custo' ? r.custo_repeticao_ano : r.rep_por_paciente;","const val = r => o === 'custo' ? r.custo_repeticao_ano : o === 'cpp' ? r.custo_por_paciente : r.rep_por_paciente;")
    rep("e.textContent = o === 'custo' ? F.short(r.custo_repeticao_ano) : F.dec(r.rep_por_paciente) + ' por pac.';","e.textContent = o === 'custo' ? F.short(r.custo_repeticao_ano) : o === 'cpp' ? F.brl(r.custo_por_paciente) + ' por pac.' : F.dec(r.rep_por_paciente) + ' por pac.';")
    rep("sm.textContent = o === 'custo' ? F.dec(r.rep_por_paciente) + ' por pac.' : F.short(r.custo_repeticao_ano) + '/ano';","sm.textContent = F.int(r.pacientes) + ' pacientes · ' + F.short(r.custo_repeticao_ano) + '/ano';")
    rep("td(r.medico); td(F.int(r.pacientes)); td(F.int(r.repeticoes)); td(F.dec(r.rep_por_paciente));","td(r.medico); td(F.int(r.pacientes)); td(F.pct(r.pct_pac_rep)); td(F.int(r.repeticoes)); td(F.dec(r.rep_por_paciente));")
    rep("td(F.pct(r.pct_proprio)); td(F.brl(r.custo_repeticao_ano));","td(F.pct(r.pct_proprio)); td(F.brl(r.custo_por_paciente)); td(F.brl(r.custo_repeticao_ano));")
    rep(".rx-fase[hidden]{display:none}",'.rx-fase[hidden]{display:none}\n.rx .rx-how{font-size:.7rem;line-height:1.45;color:var(--mu);margin:2px 0 0;font-weight:600}\n.rx .rx-how::before{content:"ⓘ ";color:var(--nv);font-weight:800}\n.rx p.rx-how.rx-how-k{margin:-6px 2px 0}')
    H=lambda t:'<p class="rx-how">'+t+'</p>'
    rep('\n\n    <section class="rx-card" id="fases">','\n    <p class="rx-how rx-how-k">Gasto = soma do valor pago à RED 8 nos 10 meses × 12/10. Repetição = exame refeito pelo mesmo paciente dentro do prazo escolhido acima; o primeiro exame nunca conta. Pacientes = pessoas diferentes (prontuário SAME), cada uma contada uma vez.</p>\n\n    <section class="rx-card" id="fases">')
    rep('as fases incluídas na seleção acima.</p></div>\n      <div class="rx-scroll"><table data-source="fases_tab"','as fases incluídas na seleção acima.</p>'+H('Cada repetição entra em uma fase pelos dias desde o exame anterior do mesmo paciente. Acumulado = soma da fase com as anteriores. % da repetição = custo da fase ÷ custo de todas as fases.')+'</div>\n      <div class="rx-scroll"><table data-source="fases_tab"')
    rep('Em amarelo, os que já têm proposta de protocolo.</p>','Em amarelo, os que já têm proposta de protocolo.</p>'+H('Por exame: soma do valor de todas as repetições no prazo escolhido, × 12/10.'))
    VE=H('Exames = quantos foram feitos no período. Repetidos = quantos deles foram repetição. % repetido = repetidos ÷ exames. "No período" = soma dos 10 meses; "por ano" = × 12/10.')
    rep('Valores por exame</h2></div>\n      <div class="rx-scroll"><table data-source="exames_tab"','Valores por exame</h2>'+VE+'</div>\n      <div class="rx-scroll"><table data-source="exames_tab"')
    rep('Médico do exame repetido comparado ao do exame anterior.</p>','Médico do exame repetido comparado ao do exame anterior.</p>'+H('Para cada repetição, olhamos quem pediu o exame anterior do mesmo paciente. Mesmo nome = mesmo médico; nome diferente = outro médico. Valores por ano.'))
    CE=H('Economia por ano = gasto com repetição por ano (no prazo escolhido) × % de redução escolhido.')
    rep('Cenários de economia</h2></div>\n      <div class="rx-sim">','Cenários de economia</h2>'+CE+'</div>\n      <div class="rx-sim">')
    rep('\n\n      <section class="rx-card" id="ranking-medicos">','\n      <p class="rx-how rx-how-k">Pacientes atendidos = pessoas diferentes (prontuário SAME) com pelo menos um exame pedido pelo médico no período. Cada paciente conta uma vez, não importa quantos pedidos ou quantas vezes o nome do médico aparece. Entram só médicos com 100 pacientes ou mais. Média = total de repetições ÷ total de pacientes desses médicos.</p>\n\n      <section class="rx-card" id="ranking-medicos">')
    rep('Comparativo · 30 primeiros</h2>','Comparativo · 30 primeiros</h2>'+H('Pacientes com repetição = % dos pacientes do médico com pelo menos um exame repetido. Repetições por paciente = repetições pedidas pelo médico ÷ pacientes atendidos. × média = repetições por paciente ÷ média. Custo por paciente = custo da repetição por ano ÷ pacientes atendidos.'))
    rep('\n      <section class="rx-card" id="u-fases">','      <p class="rx-how rx-how-k">Mesmo cálculo dos eletivos, mas o prazo é em horas, pela data e hora do pedido; vale também quando o paciente passa do PS para a internação. Por dia = exames repetidos ÷ dias do período. Valores por ano = 10 meses × 12/10.</p>\n      <section class="rx-card" id="u-fases">')
    rep('Em quanto tempo o mesmo exame é pedido de novo para o mesmo paciente. Em destaque, as fases incluídas na seleção acima.</p>','Em quanto tempo o mesmo exame é pedido de novo para o mesmo paciente. Em destaque, as fases incluídas na seleção acima.</p>'+H('Cada repetição entra em uma fase pelas horas desde o pedido anterior do mesmo exame. Acumulado = soma da fase com as anteriores.'))
    rep('no pronto-socorro e nas enfermarias a repetição tende a ser mais evitável.</p>','no pronto-socorro e nas enfermarias a repetição tende a ser mais evitável.</p>'+H('Área = setor que pediu o exame repetido. % repetidos = exames repetidos ÷ exames da área. Valores por ano.'))
    rep('Exames que mais custam em repetição · por ano</h2>','Exames que mais custam em repetição · por ano</h2>'+H('Por exame: soma do valor de todas as repetições no prazo escolhido, × 12/10.'))
    rep('Valores por exame</h2></div>\n        <div class="rx-scroll"><table>','Valores por exame</h2>'+VE+'</div>\n        <div class="rx-scroll"><table>')
    rep('Cenários de economia</h2></div>\n        <div class="rx-sim">','Cenários de economia</h2>'+CE+'</div>\n        <div class="rx-sim">')
    return s
